        # Check if in activation zone and moving slowly
        if 5.0 <= x <= 10.0 and abs(vx_p) < 0.5:
            state['phase'] = 'UNLOCK'
            state['t'] = 0
            state['last_unlock_step'] = step_count
        else:
            # Navigate using whiskers and position
            if front < 0.5:
                # Too close to a wall, reduce forward force
                fx = 0.0
            else:
                # Move towards activation zone
                if x < 5.0:
                    fx = 15.0
                else:
                    fx = 10.0 * (7.0 - x) - 5.0 * vx_p
            fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
    elif state['phase'] == 'UNLOCK':
        # Apply unlock force
        fx_cmd = -35.0  # Must be < -34.0 N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Adjust based on whiskers to avoid walls
        if front < 0.5:
            fx_cmd = max(fx_cmd - 10.0, -35.0)

        # Check if we've been in unlock phase for 5 steps
        if step_count - state['last_unlock_step'] >= 5:
            state['phase'] = 'ESCAPE'

        fx, fy = fx_cmd, fy_cmd
    elif state['phase'] == 'ESCAPE':
        # Navigate toward exit
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp

        # Check if in exit zone
        if x > 15.0 and 0.5 <= y <= 2.5:
            state['phase'] = 'HOLD'
    elif state['phase'] == 'HOLD':
        # Hold position in exit zone
        fx, fy = 0.0, w_comp

    # Apply force with safety check
    if state['phase'] in ['APPROACH', 'UNLOCK', 'ESCAPE']:
        sandbox.apply_agent_force(fx, fy)

